+                                               adminMAC, vlan, MAC, !!vlan));
+            VIR_FREE(MAC);
+            VIR_FREE(adminMAC);
+            virNetDevVlanFree(vlan);
+        }
     }

     virNetlinkEventRemoveClient(0, macaddr, NETLINK_ROUTE);

     return ret;
 }



